# ----------------- Inactivity & Satisfaction Timers -----------------
PENDING_SATISFACTION_CHECKS = {}

async def inactivity_closing_timer(phone: str, prompt_timestamp: float, raw_chat_id: str = "", customer_name: str = ""):
    """
    Waits 35 seconds (>30s) after the satisfaction question is asked.
    If the customer has not responded, automatically sends:
    'מקווה שעזרתי לך היום, אני כאן לכל שאלה נוספת. בשורות טובות, שפע ברכה והצלחה וכל טוב! 🌟'
    """
    await asyncio.sleep(35)
    
    # Check if this timer was cancelled by an incoming reply
    if PENDING_SATISFACTION_CHECKS.get(phone) != prompt_timestamp:
        return
    
    PENDING_SATISFACTION_CHECKS[phone] = None
    
    name_str = f" {customer_name}" if (customer_name and customer_name not in COMMON_NON_NAMES) else ""
    shabbat_suffix = " שבת שלום ומבורכת," if is_shabbat_time_or_greeting() else ""
    closing_msg = f"מקווה שעזרתי לך היום{name_str}, אני כאן לכל שאלה נוספת.{shabbat_suffix} בשורות טובות, שפע ברכה והצלחה וכל טוב! 🌟"
    send_whatsapp_message(phone, closing_msg, raw_chat_id)
    save_chat_message(phone, "agent", closing_msg)
    print(f"[Inactivity Closing Sent] To {phone} after 35s timeout.")

# ----------------- Greeting Detection -----------------
def is_thank_you_or_closing(text: str, recent_history: str = "") -> bool:
    clean = re.sub(r"[^\w\sא-ת]", " ", text or "").strip().lower()
    words = clean.split()
    if not words or len(words) > 7:
        return False
    closing_phrases = [
        "תודה", "תודה רבה", "תודה לך", "תודה רבה לך", "תודה על העזרה", "תודה על המענה",
        "יישר כח", "יישר כוח", "שכוייח", "תזכו למצוות", "תבורכו", "מעולה תודה",
        "אחלה תודה", "יופי תודה", "בסדר גמור תודה", "מצוין תודה", "הבנתי תודה",
        "תודה רבה עזרת לי", "עזרת לי מאוד", "עזרתם לי מאוד", "יום טוב", "שבוע טוב",
        "שבת שלום", "חג שמח", "להתראות", "ביי", "לילה טוב",
        "לא תודה", "לא הכל טוב", "זה הכל תודה", "זהו תודה", "הכל בסדר תודה"
    ]
    if any(phrase in clean for phrase in closing_phrases):
        return True
    # If the bot just asked "האם אוכל לעזור לך במשהו נוסף?" and customer replies "לא" / "לא הכל בסדר" / "זה הכל"
    if "במשהו נוסף" in (recent_history or "") and clean in ["לא", "לא הכל בסדר", "לא צריך", "זה הכל", "זהו", "הכל טוב"]:
        return True
    return False

