def detect_chosen_warranty_track(text: str) -> str:
    """
    Detects if the customer is selecting a specific warranty track ('yemot', 'galut', or 'geula')
    to purchase/reserve a device (rather than asking 'what is the difference between tracks?').
    Returns 'yemot', 'galut', 'geula', or ''.
    """
    clean = (text or "").strip().lower()
    if not clean:
        return ""
    # If customer is asking to explain the differences, it is not a final track selection yet
    if any(q in clean for q in ["מה ההבדל", "הבדלים", "תפרט", "הסבר על", "מה זה מסלול", "טבלת השוואה", "קובץ pdf"]):
        return ""
    if any(w in clean for w in ["ימות המשיח", "ימות משיח", "המומלץ", "מסלול המומלץ", "אחריות מעבדה", "650", "870", "950"]):
        return "yemot"
    if any(w in clean for w in ["מסלול גלות", "בגלות", "גלות", "אחריות יבואן", "יבואן רשמי", "550", "770", "850"]):
        return "galut"
    if any(w in clean for w in ["מסלול גאולה", "גאולה"]):
        return "geula"
    return ""


def is_warranty_followup_confirmation(text: str, history_text: str = "") -> bool:
    clean = (text or "").strip().lower()

    # If the customer is selecting a track to reserve/buy (e.g. "אני בוחר בימות המשיח" or "ימות המשיח" after being asked which track they choose),
    # let the device reservation & Bit payment handler process it!
    if detect_chosen_warranty_track(clean) and any(
        p in (history_text or "") for p in ["באיזה מסלול אחריות תרצה לבחור", "איזה מסלול לרשום לך", "נשארו יחידות אחרונות במלאי"]
    ):
        return False

    # 1. Direct and proactive inquiry about differences or warranty explanation
    direct_warranty_triggers = [
        "הבדל", "הבדלים", "שוני",
        "מסלולי אחריות", "מסלולי האחריות", "סוגי אחריות",
        "פירוט אחריות", "פירוט האחריות", "הסבר על האחריות", "הסבר על מסלולי",
        "האחריות שלכם", "טבלת אחריות", "טבלת השוואה", "קובץ אחריות", "קובץ pdf",
        "מה זה ימות המשיח", "מה זה גלות", "מה זה מסלול"
    ]
    if any(phrase in clean for phrase in direct_warranty_triggers):
        return True

    # 2. Positive followups ONLY when the bot specifically asked if they want the extended warranty explanation
    asked_for_warranty_explanation = any(m in (history_text or "") for m in [
        "האם תרצה פירוט מורחב של ההבדלים", "פירוט מורחב של ההבדלים המלאים בין מסלולי האחריות"
    ])
    positive_signals = [
        "כן", "אשמח", "תפרט", "פרט", "תשלח", "שלח", "תסביר",
        "רוצה לדעת", "אשמח לפירוט", "כן אשמח", "תשלח לי", "בטח", "ודאי",
        "שלח לי", "אשמח להסבר", "תן פרטים"
    ]
    is_positive = any(clean == sig or clean.startswith(sig) or f" {sig} " in f" {clean} " for sig in positive_signals)
    return asked_for_warranty_explanation and is_positive


def is_repair_or_smartphone_context(text: str) -> bool:
    """
    Returns True if the text is about a lab repair/part (screen, battery, charging port, repair)
    OR about a smartphone (Galaxy/Samsung A14/A17/S24, iPhone, Redmi).
    Warranty tracks (גלות / ימות המשיח / גאולה) are strictly ONLY for sales of Kosher & Half-Touch devices!
    """
    clean = (text or "").lower()
    repair_and_part_terms = [
        "מסך", "החלפת מסך", "סוללה", "בטריה", "שקע טעינה", "שקע", "תיקון", "לתקן",
        "מעבדה", "נשבר", "שבור", "קורוזיה", "נפל למים", "חלק", "חלפים"
    ]
    smartphone_terms = [
        "גלקסי", "galaxy", "סמסונג", "samsung", "אייפון", "iphone", "redmi", "רדמי", "poco", "פוקו"
    ]
    if any(t in clean for t in repair_and_part_terms):
        return True
    if any(t in clean for t in smartphone_terms) or bool(re.search(r"\b[aAsSmM]\d{1,2}\b", clean)):
        return True
    return False


def ensure_warranty_question_in_device_quote(reply: str, customer_msg: str, recent_history: str = "") -> str:
    """
    Ensures Kosher & Half-Touch device purchase price quotes include persuasive recommendation for
    מסלול ימות המשיח ⭐ and active sales closing with scarcity urgency ("נשארו יחידות אחרונות במלאי! תרצה שנשריין..."),
    while STRICTLY stripping/blocking warranty tracks from any lab repair or smartphone messages!
    """
    clean_reply = (reply or "").strip()
    clean_msg = (customer_msg or "").strip().lower()
    combined_ctx = f"{clean_msg} {clean_reply.lower()} {(recent_history or '').lower()}"

    # Rule C: If this is a lab repair (screen, battery, port) or smartphone context, NEVER mention Kosher device warranty tracks!
    if is_repair_or_smartphone_context(combined_ctx):
        clean_reply = re.sub(
            r"\s*האם\s+תרצה\s+פירוט\s+מורחב\s+של\s+ההבדלים(?:\s+המלאים)?\s+בין\s+מסלולי\s+האחריות\?\s*😃?\s*",
            " ",
            clean_reply
        ).strip()
        return clean_reply

    # Strip any passive closing ("האם אוכל לעזור במשהו נוסף", "האם הצלחתי לעזור") if the reply is quoting a device price!
    kosher_device_indicators = ["גלות", "ימות המשיח", "f21", "f22", "f25", "qin", "מכשיר כשר", "טלפון כשר", "חצי טאץ", "מקשים"]
    has_kosher_device_price = any(w in clean_reply.lower() for w in ["גלות", "ימות המשיח"]) or (
        ("₪" in clean_reply or "שח" in clean_reply or 'ש"ח' in clean_reply)
        and any(d in combined_ctx for d in kosher_device_indicators)
    )
    if has_kosher_device_price:
        clean_reply = re.sub(
            r"\s*(?:האם\s+הצלחתי\s+לעזור[^\n]*|האם\s+אוכל\s+לעזור(?:\s+לך)?\s+במשהו\s+נוסף\??\s*😃?|האם\s+אפשר\s+לעזור\s+במשהו\s+נוסף\??\s*😃?)\s*$",
            "",
            clean_reply
        ).strip()

    already_has_sales_cta = any(q in clean_reply for q in [
        "נשארו יחידות אחרונות", "תרצה שנשריין", "תרצה לשריין", "באיזה מסלול אחריות תרצה לבחור"
    ])
    if has_kosher_device_price and not already_has_sales_cta:
        # Replace generic warranty question if LLM added it, and append strong sales close + ימות המשיח recommendation
        clean_reply = re.sub(
            r"\s*האם\s+תרצה\s+פירוט\s+מורחב\s+של\s+ההבדלים(?:\s+המלאים)?\s+בין\s+מסלולי\s+האחריות\?\s*😃?\s*$",
            "",
            clean_reply
        ).strip()
        sales_closing = (
            "⭐ *המלצה שלנו:* ב*מסלול ימות המשיח* אתה מקבל אחריות מעבדה מלאה אצלנו בחדרה עם תיקון אקספרס תוך שעתיים (במקום להמתין 3 שבועות ליבואן!), מכשיר חלופי חינם והעברת נתונים ללא עלות!\n\n"
            "🔥 נשארו יחידות אחרונות במלאי! תרצה שנשריין עבורך מכשיר כעת כדי שלא תיתקע בלי? באיזה מסלול אחריות תרצה לבחור (ימות המשיח ⭐ המומלץ או גלות)? 😃"
        )
        if "תיקון אקספרס" in clean_reply:
            sales_closing = "🔥 נשארו יחידות אחרונות במלאי! תרצה שנשריין עבורך מכשיר כעת כדי שלא תיתקע בלי? באיזה מסלול אחריות תרצה לבחור (ימות המשיח ⭐ המומלץ או גלות)? 😃"
        return clean_reply.rstrip() + "\n\n" + sales_closing
    return clean_reply

# ----------------- Database Initialization & JSON Backup Sync -----------------

BACKUP_KB_JSON_PATH = os.path.join(
    os.path.dirname(DB_PATH) if (DB_PATH != ":memory:" and os.path.dirname(DB_PATH)) else "/tmp",
    "learned_kb_cache.json"
)

def sync_learned_kb_to_json():
    """Exports learned_kb to local JSON cache for extra durability across restarts."""
    try:
        conn = sqlite3.connect(DB_PATH)
        rows = conn.execute("SELECT DISTINCT keywords, answer FROM learned_kb").fetchall()
        conn.close()
        data = [
            {"keywords": r[0], "answer": r[1]}
            for r in rows
            if r[0] and r[1] and not is_admin_meta_or_error_correction(r[1])
        ]
        with open(BACKUP_KB_JSON_PATH, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
    except Exception:
        pass

def find_matching_learned_knowledge(message_text: str, recent_history: str = "") -> str:
    """
    Direct deterministic lookup for learned rules and known product prices.
    Uses whole-word, phrase, and conversation-context matching, preventing spurious matches on stopwords.
    Never returns canned KB answers when the customer is disputing/challenging a price or scheduling!
    """
    if is_scheduling_request(message_text) or is_price_dispute_or_challenge(message_text, recent_history):
        return ""

    clean = (message_text or "").lower().strip()
    clean_no_punct = "".join([c if c.isalnum() or c.isspace() else " " for c in clean]).strip()
    clean_words = set(clean_no_punct.split())
    ctx_clean = "".join([c if c.isalnum() or c.isspace() else " " for c in f"{clean} {(recent_history or '').lower()}"])
    ctx_words = set(ctx_clean.split())

    STOP_KEYWORDS = {
        "חנות", "בעל", "בית", "איך", "מה", "זה", "שלי", "שלך", "הוא", "היא",
        "יש", "אין", "לא", "כן", "פה", "כאן", "טוב", "תודה", "שלום", "היי",
        "של", "על", "עם", "את", "או", "גם", "רק", "עוד", "כל", "מחיר", "המחיר"
    }
    MODEL_TOKENS = {"f21", "f21p", "f21pro", "f22", "f22p", "f22pro", "f25", "f25p", "f25pro", "qin", "a14", "a17", "s24"}
    is_asking_color = any(w in clean for w in ["צבע", "צבעים", "באיזה צבע"])
    is_asking_repair = any(w in clean for w in ["מסך", "סוללה", "שקע"])

    # 1. Check dynamic database learned knowledge FIRST for specific follow-up answers (e.g. colors, stock details, specific rules taught by Admin)
    try:
        conn = sqlite3.connect(DB_PATH)
        rows = conn.execute("SELECT keywords, answer FROM learned_kb ORDER BY id DESC").fetchall()
        conn.close()
        for kw_str, ans in rows:
            if not kw_str or not ans or is_admin_meta_or_error_correction(ans):
                continue
            # Skip any legacy outdated F21P 650/750 price row if it somehow exists
            if any(m in kw_str.lower() for m in ["f21", "f21p"]) and "650" in ans and "750" in ans:
                continue
            # If user is asking about color, only match KB entries that actually talk about colors
            if is_asking_color and not any(c in (kw_str + " " + ans) for c in ["צבע", "שחור", "לבן", "כחול", "אפור", "כסוף", "זהב"]):
                continue
            keywords = [k.strip().lower() for k in kw_str.replace(";", ",").replace("|", ",").split(",") if k.strip()]
            for kw in keywords:
                if len(kw) < 3 or kw in STOP_KEYWORDS:
                    continue
                kw_clean = "".join([c if c.isalnum() or c.isspace() else " " for c in kw]).strip()
                if not kw_clean or len(kw_clean) < 3 or kw_clean in STOP_KEYWORDS:
                    continue
                if "מסך" not in kw and "תיקון" not in kw and is_asking_repair:
                    continue
                # Direct match in current message
                if re.search(rf"(?:^|\s){re.escape(kw)}(?:$|\s)", clean) or re.search(rf"(?:^|\s){re.escape(kw_clean)}(?:$|\s)", clean_no_punct):
                    return sanitize_admin_leakage(ans)
                # Contextual match for follow-up questions (e.g. keyword "צבעים f21" when message has "צבעים" and conversation has "f21")
                kw_tokens = [t for t in kw_clean.split() if t not in STOP_KEYWORDS]
                non_model_tokens = [t for t in kw_tokens if t not in MODEL_TOKENS]
                if len(kw_tokens) >= 2 and non_model_tokens:
                    if all(t in clean_words for t in non_model_tokens) and all(t in ctx_words for t in kw_tokens):
                        return sanitize_admin_leakage(ans)
    except Exception:
        pass

    # 2. Check PERMANENT_LEARNED_KB for authoritative device prices & repair prices
    for item in PERMANENT_LEARNED_KB:
        keywords = [k.strip().lower() for k in item["keywords"].split(",") if k.strip()]
        for kw in keywords:
            if len(kw) < 3 or kw in STOP_KEYWORDS:
                continue
            kw_clean = "".join([c if c.isalnum() or c.isspace() else " " for c in kw]).strip()
            if not kw_clean or len(kw_clean) < 3 or kw_clean in STOP_KEYWORDS:
                continue
            # If the keyword is for a general device purchase without 'מסך'/'תיקון', skip if the customer is asking about a screen/repair or specifically about colors
            if "מסך" not in kw and "תיקון" not in kw and is_asking_repair:
                continue
            if "צבע" not in kw and is_asking_color:
                continue
            if re.search(rf"(?:^|\s){re.escape(kw)}(?:$|\s)", clean) or (re.search(rf"(?:^|\s){re.escape(kw_clean)}(?:$|\s)", clean_no_punct)):
                return item["answer"]

    return ""

def sync_contacts_to_json():
    """Exports all contacts from SQLite to local JSON cache for extra durability."""
    try:
        conn = sqlite3.connect(DB_PATH)
        rows = conn.execute("SELECT phone, name FROM contacts").fetchall()
        conn.close()
        data = {r[0]: r[1] for r in rows if r[0] and r[1]}
        with open(BACKUP_JSON_PATH, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
    except Exception:
        pass

def init_db():
    try:
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute("""
            CREATE TABLE IF NOT EXISTS learned_kb (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                keywords TEXT,
                answer TEXT,
                created_at TEXT
            )
        """)
        # Deduplicate learned_kb and purge any stale F21/F22/F25 entries or leaked Admin meta-comments
        try:
            c.execute("""
                DELETE FROM learned_kb WHERE id NOT IN (
                    SELECT MIN(id) FROM learned_kb GROUP BY keywords, answer
                )
            """)
            c.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_learned_kb_kw_ans ON learned_kb(keywords, answer)")
            c.execute(
                "DELETE FROM learned_kb WHERE keywords LIKE '%לקבוע%' OR keywords LIKE '%לתאם%' OR keywords LIKE '%תור%' "
                "OR keywords LIKE '%f21%' OR keywords LIKE '%f22%' OR keywords LIKE '%f25%' "
                "OR answer LIKE '%לא מתאים%' OR answer LIKE '%#2:%' OR answer LIKE '%נתת ללקוח%' "
                "OR answer LIKE '%עשית טעות%' OR answer LIKE '%טעית%' OR answer LIKE '%שגוי%'"
            )
        except Exception:
            pass
        c.execute("""
            CREATE TABLE IF NOT EXISTS installations_schedule (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                phone TEXT,
                customer_name TEXT,
                callback_phone TEXT,
                details TEXT,
                scheduled_time TEXT,
                status TEXT,
                created_at TEXT
            )
        """)
        try:
            c.execute("ALTER TABLE installations_schedule ADD COLUMN callback_phone TEXT")
        except Exception:
            pass
        c.execute("""
            CREATE TABLE IF NOT EXISTS customer_requests (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                phone TEXT,
                system_name TEXT,
                request_text TEXT,
                action_taken TEXT,
                upsell_offer TEXT,
                status TEXT,
                created_at TEXT
            )
        """)
        c.execute("""
            CREATE TABLE IF NOT EXISTS contacts (
                phone TEXT PRIMARY KEY,
                name TEXT,
                created_at TEXT,
                updated_at TEXT
            )
        """)
        # 1. Seed from PERMANENT_CONTACTS
        for p, n in PERMANENT_CONTACTS.items():
            norm_p = normalize_phone(p)
            c.execute("""
                INSERT OR IGNORE INTO contacts (phone, name, created_at, updated_at)
                VALUES (?, ?, datetime('now'), datetime('now'))
            """, (norm_p, n))

        # 2. Restore from JSON cache if present
        if os.path.exists(BACKUP_JSON_PATH):
            try:
                with open(BACKUP_JSON_PATH, "r", encoding="utf-8") as f:
                    cached = json.load(f)
                if isinstance(cached, dict):
                    for cp, cn in cached.items():
                        norm_cp = normalize_phone(cp)
                        if norm_cp and cn:
                            c.execute("""
                                INSERT OR IGNORE INTO contacts (phone, name, created_at, updated_at)
                                VALUES (?, ?, datetime('now'), datetime('now'))
                            """, (norm_cp, str(cn).strip()))
            except Exception:
                pass

        c.execute("""
            CREATE TABLE IF NOT EXISTS conversation_history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                phone TEXT,
                role TEXT,
                message TEXT,
                created_at TEXT
            )
        """)
        c.execute("""
            CREATE TABLE IF NOT EXISTS subscribers (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                phone TEXT UNIQUE,
                name TEXT,
                system_name TEXT,
                status TEXT,
                current_level TEXT,
                device_id TEXT,
                whitelist TEXT,
                renewal_date TEXT
            )
        """)
        c.execute("SELECT COUNT(*) FROM subscribers")
        if c.fetchone()[0] == 0:
            c.executemany("""
                INSERT INTO subscribers (phone, name, system_name, status, current_level, device_id, whitelist, renewal_date)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """, [
                ("972524489102", "דוד כהן", "נטספרק", "active", "רחבה (350 ₪/שנה)", "NS-88412", "gov.il, bankhapoalim.co.il", "15/11/2026"),
                ("972549182736", "משה לוי", "כשר פליי", "active", "כשר פליי מורחב (200 ₪/שנה)", "KP-30941", "clalit.co.il, leumi.co.il", "01/02/2027"),
                ("972528819203", "שמעון מזרחי", "כשר פליי", "expired", "כשר פליי מורחב + דפדפן (300 ₪/שנה)", "KP-19204", "gov.il", "01/10/2026"),
                ("972501234567", "יוסף אברהמי", "כשר פליי", "active", "כשר פליי בסיסי (250 ₪ חד-פעמי)", "KP-B-102", "bankleumi.co.il, waze", "ללא תפוגה (פעיל עד החלפת מכשיר)"),
            ])
        # 3. Seed PERMANENT_LEARNED_KB into learned_kb
        for item in PERMANENT_LEARNED_KB:
            c.execute("""
                INSERT OR IGNORE INTO learned_kb (keywords, answer, created_at)
                VALUES (?, ?, datetime('now'))
            """, (item["keywords"], item["answer"]))

        # 4. Restore learned_kb from JSON cache if present (skipping any stale F21/F22/F25 or admin meta-error rows)
        if os.path.exists(BACKUP_KB_JSON_PATH):
            try:
                with open(BACKUP_KB_JSON_PATH, "r", encoding="utf-8") as f:
                    kb_cached = json.load(f)
                if isinstance(kb_cached, list):
                    for item in kb_cached:
                        if isinstance(item, dict) and item.get("keywords") and item.get("answer"):
                            kw_l = str(item["keywords"]).lower()
                            ans_s = str(item["answer"])
                            if any(k in kw_l for k in ["f21", "f22", "f25", "לקבוע", "לתאם", "תור"]):
                                continue
                            if is_admin_meta_or_error_correction(ans_s):
                                continue
                            c.execute("""
                                INSERT OR IGNORE INTO learned_kb (keywords, answer, created_at)
                                VALUES (?, ?, datetime('now'))
                            """, (item["keywords"], sanitize_admin_leakage(ans_s)))
            except Exception:
                pass

        conn.commit()
        conn.close()
        sync_contacts_to_json()
        sync_learned_kb_to_json()
    except Exception as e:
        print(f"[Init DB Notice]: {e}")

init_db()

# ----------------- Helper Functions -----------------
def parse_green_api_credentials():
    """Extracts instance base URL, token, and clean sendMessage URL from WHATSAPP_API_URL."""
    clean = (WHATSAPP_API_URL or "").strip().strip('"').strip("'").rstrip("/")
    if "/sendMessage/" in clean:
        base, token = clean.split("/sendMessage/", 1)
        token = token.strip().strip("/")
        return base, token, f"{base}/sendMessage/{token}"
    return None, None, clean

def get_green_api_base_and_token():
    base, token, _ = parse_green_api_credentials()
    return base, token


def send_whatsapp_file_by_url(phone: str, file_url: str, file_name: str, caption: str = "", raw_chat_id: str = "") -> bool:
    clean_phone = normalize_phone(phone)
    if not clean_phone and not raw_chat_id:
        return False
    base, token, _ = parse_green_api_credentials()
    if not base or not token:
        return False
    send_file_url = f"{base}/sendFileByUrl/{token}"
    target_chat_id = f"{clean_phone}@c.us" if clean_phone else raw_chat_id
    payload = {
        "chatId": target_chat_id,
        "urlFile": file_url,
        "fileName": file_name,
        "caption": caption
    }
    try:
        resp = http_session.post(send_file_url, json=payload, timeout=12)
        print(f"[WhatsApp File Sent] To: {target_chat_id}, Status: {resp.status_code}, Resp: {resp.text[:100]}")
        return resp.status_code == 200
    except Exception as exc:
        print(f"[WhatsApp File Send Notice]: {exc}")
        return False

def send_whatsapp_message(phone: str, text: str, raw_chat_id: str = "") -> bool:
    clean_phone = normalize_phone(phone)
    clean_text = (text or "").strip()
    if (not clean_phone and not raw_chat_id) or not clean_text:
        print(f"[WhatsApp Skip] Invalid phone or empty text: phone={clean_phone}")
        return False

    # Final safety guard on customer-facing messages (never allow Admin meta-criticism to leak to a customer)
    if not clean_text.startswith(("❓", "✅", "🕒", "📞", "💳", "📦", "ℹ️", "⚠️")):
        clean_text = sanitize_admin_leakage(clean_text)

    _, _, send_url = parse_green_api_credentials()
    if not send_url:
        print(f"[WhatsApp DryRun] No WHATSAPP_API_URL configured. Message to {clean_phone}: {clean_text[:60]}")
        return False

    target_chat_id = f"{clean_phone}@c.us" if clean_phone else raw_chat_id
    payload = {
        "chatId": target_chat_id,
        "message": clean_text
    }
    try:
        resp = http_session.post(send_url, json=payload, timeout=8)
        print(f"[WhatsApp Sent] To: {target_chat_id}, Status: {resp.status_code}, Response: {resp.text[:100]}")
        return resp.status_code == 200
    except Exception as exc:
        print(f"[WhatsApp Send Error]: {exc}")
        return False

def lookup_subscriber(phone: str, message_text: str = "") -> dict:
    """Checks subscriber status in NetSpark & KosherPlay database by phone or name mentioned in text."""
    norm = normalize_phone(phone)
    try:
        conn = sqlite3.connect(DB_PATH)
        row = None
        if norm:
            row = conn.execute(
                "SELECT name, system_name, status, current_level, device_id, whitelist, renewal_date, phone "
                "FROM subscribers WHERE phone = ? OR phone LIKE ? LIMIT 1",
                (norm, f"%{norm[-9:]}%" if len(norm) >= 9 else f"%{norm}%")
            ).fetchone()
        if not row and message_text:
            all_subs = conn.execute(
                "SELECT name, system_name, status, current_level, device_id, whitelist, renewal_date, phone FROM subscribers"
            ).fetchall()
            for s in all_subs:
                if s[0] and s[0] in message_text:
                    row = s
                    break
        conn.close()
        if row:
            return {
                "found": True,
                "name": row[0],
                "system": row[1],
                "status": row[2],
                "level": row[3],
                "deviceId": row[4],
                "whitelist": row[5],
                "renewalDate": row[6],
                "phone": row[7]
            }
    except Exception:
        pass
    return {"found": False}

def get_learned_knowledge() -> str:
    try:
        conn = sqlite3.connect(DB_PATH)
        rows = conn.execute("SELECT keywords, answer FROM learned_kb").fetchall()
        conn.close()
        if not rows:
            return "אין עדיין כללים נוספים."
        return "\n".join([f"- מילות זיהוי ({r[0]}): תשובה שנלמדה בעבר: {r[1]}" for r in rows])
    except Exception:
        return "אין עדיין כללים נוספים."

def save_contact_name(phone: str, name: str):
    clean_name = name.strip()
    norm_phone = normalize_phone(phone)
    if not clean_name or not norm_phone or clean_name in COMMON_NON_NAMES:
        return
    # Guard: never overwrite permanent admin/owner contacts
    if norm_phone in PERMANENT_CONTACTS:
        return
    try:
        conn = sqlite3.connect(DB_PATH)
        conn.execute("""
            INSERT INTO contacts (phone, name, created_at, updated_at)
            VALUES (?, ?, ?, ?)
            ON CONFLICT(phone) DO UPDATE SET name=excluded.name, updated_at=excluded.updated_at
        """, (norm_phone, clean_name, datetime.now().isoformat(), datetime.now().isoformat()))
        conn.commit()
        conn.close()
        sync_contacts_to_json()
    except Exception as exc:
        print(f"[Save Contact Notice]: {exc}")

def extract_name_from_text(text: str) -> str:
    cleaned = re.sub(r"[^\w\sא-ת]", " ", text or "").strip()
    if not cleaned:
        return ""

    # 1. Explicit self-identification patterns only
    explicit_patterns = [
        r"(?:שמי(?:\s+הוא)?|קוראים\s+לי|השם\s+שלי(?:\s+הוא)?)\s+([א-ת]{2,15})",
        r"^(?:שלום\s*,?\s*)?(?:מדבר|מדברת)\s+([א-ת]{2,15})",
        r"^(?:אני|זה)\s+([א-ת]{2,15})\s*$",
        r"^([א-ת]{2,15})\s+כאן\s*$"
    ]
    for pattern in explicit_patterns:
        match = re.search(pattern, cleaned)
        if match:
            candidate = match.group(1).strip()
            if candidate not in COMMON_NON_NAMES:
                return candidate

    # 2. Strict 1-2 words name ONLY if all words are valid Hebrew letters and NOT in COMMON_NON_NAMES
    words = cleaned.split()
    if 1 <= len(words) <= 2:
        if all(re.fullmatch(r"[א-ת]{2,15}", w) and w not in COMMON_NON_NAMES for w in words):
            return words[0]

    return ""

def get_contact_name(phone: str) -> str:
    norm = normalize_phone(phone)
    if not norm:
        return ""
    if norm in PERMANENT_CONTACTS:
        return PERMANENT_CONTACTS[norm].split()[0]
    for p, n in PERMANENT_CONTACTS.items():
        clean_p = normalize_phone(p)
        if clean_p and len(clean_p) >= 9 and len(norm) >= 9:
            if clean_p[-9:] == norm[-9:]:
                return n.split()[0]

    try:
        conn = sqlite3.connect(DB_PATH)
        row = conn.execute(
            "SELECT name FROM contacts WHERE phone = ? OR phone LIKE ? LIMIT 1",
            (norm, f"%{norm[-9:]}%" if len(norm) >= 9 else f"%{norm}%")
        ).fetchone()
        conn.close()
        if row and row[0] and row[0].strip() not in COMMON_NON_NAMES:
            return row[0].strip().split()[0]
    except Exception:
        pass

    return ""

def save_chat_message(phone: str, role: str, text: str):
    norm_phone = normalize_phone(phone)
    clean_text = text.strip()
    if not norm_phone or not clean_text:
        return
    try:
        conn = sqlite3.connect(DB_PATH)
        conn.execute("""
            INSERT INTO conversation_history (phone, role, message, created_at)
            VALUES (?, ?, ?, ?)
        """, (norm_phone, role, clean_text, datetime.now().isoformat()))
        conn.commit()
        conn.close()
    except Exception:
        pass

def get_recent_chat_history(phone: str, limit: int = 6) -> str:
    norm_phone = normalize_phone(phone)
    if not norm_phone:
        return ""
    try:
        conn = sqlite3.connect(DB_PATH)
        rows = conn.execute("""
            SELECT role, message FROM conversation_history
            WHERE phone = ? OR phone LIKE ?
            ORDER BY id DESC LIMIT ?
        """, (norm_phone, f"%{norm_phone[-9:]}%" if len(norm_phone) >= 9 else f"%{norm_phone}%", limit)).fetchall()
        conn.close()
        if not rows:
            return ""
        rows.reverse()
        lines = []
        for r, msg in rows:
            sender = "לקוח" if r == "customer" else "סוכן"
            lines.append(f"[{sender}]: {msg}")
        return "\n".join(lines)
    except Exception:
        return ""

def has_already_greeted_customer(phone: str) -> bool:
    norm_phone = normalize_phone(phone)
    if not norm_phone:
        return False
    try:
        conn = sqlite3.connect(DB_PATH)
        count = conn.execute("""
            SELECT COUNT(*) FROM conversation_history
            WHERE (phone = ? OR phone LIKE ?) AND role = 'agent'
        """, (norm_phone, f"%{norm_phone[-9:]}%" if len(norm_phone) >= 9 else f"%{norm_phone}%")).fetchone()[0]
        conn.close()
        return count > 0
    except Exception:
        return False


def get_conversation_message_count(phone: str) -> int:
    norm_phone = normalize_phone(phone)
    if not norm_phone:
        return 0
    try:
        conn = sqlite3.connect(DB_PATH)
        count = conn.execute("""
            SELECT COUNT(*) FROM conversation_history
            WHERE phone = ? OR phone LIKE ?
        """, (norm_phone, f"%{norm_phone[-9:]}%" if len(norm_phone) >= 9 else f"%{norm_phone}%")).fetchone()[0]
        conn.close()
        return count
    except Exception:
        return 0

def strip_customer_name(text: str, name: str) -> str:
    if not name or name in COMMON_NON_NAMES:
        return text
    cleaned = text
    # Strip from start: e.g. "ערן, ", "היי ערן, ", "שלום ערן: "
    cleaned = re.sub(rf"^(?:שלום|היי|הי|אהלן)?[\s,]*{re.escape(name)}[\s,:-]*", "", cleaned, flags=re.IGNORECASE).strip()
    # Strip vocative in middle: e.g. "אני מבין ערן ש..." -> "אני מבין ש..."
    cleaned = re.sub(rf"[\s,]+{re.escape(name)}[\s,]+", " ", cleaned).strip()
    # Strip from end: e.g. "... ערן." -> "..."
    cleaned = re.sub(rf"[\s,]+{re.escape(name)}[?!.]*$", "", cleaned).strip()
    return cleaned

def purge_unwanted_phrases(text: str) -> str:
    cleaned = text
    cleaned = re.sub(r"בודק(?:\s+זאת|\s+כעת)?\s+מול\s+המעבדה(?:\s+שלנו)?", "בודק כעת את המחיר העדכני", cleaned)
    cleaned = re.sub(r"מול\s+המעבדה(?:\s+שלנו)?", "את המחיר העדכני", cleaned)
    cleaned = re.sub(r"[ \t]{2,}", " ", cleaned).strip()
    return cleaned

def apply_customer_name_guard(reply_text: str, customer_name: str, already_greeted: bool, msg_count: int = 2, is_closing: bool = False) -> str:
    cleaned = reply_text.strip()

    # Strip unwanted prompts asking for customer's name
    cleaned = re.sub(
        r"(?:ו?איך\s+קוראים\s+לך(?:\s+כדי\s+שאדע\s+למי\s+לפנות)?[\s?!.,]*|ו?מה\s+שמך(?:\s+בבקשה)?[\s?!.,]*|תגיד\s+מה\s+השם\s+שלך[\s?!.,]*|למי\s+לפנות[\s?!.,]*)",
        "",
        cleaned,
        flags=re.IGNORECASE
    ).strip()

    cleaned = purge_unwanted_phrases(cleaned)

    if not customer_name or customer_name in COMMON_NON_NAMES:
        return cleaned

    is_start = (msg_count <= 1 and not already_greeted)
    is_middle = (msg_count in [4, 5])

    # 1. End of conversation (סוף): Name is warmly allowed
    if is_closing:
        return cleaned

    # 2. Beginning of conversation (התחלה): Name is used with greeting
    if is_start:
        has_name = customer_name in cleaned
        has_how_are_you = any(p in cleaned for p in ["מה שלומך", "מה נשמע"])
        if not has_name or not has_how_are_you:
            salutation = f"שלום {customer_name}, מה שלומך?"
            greeting_pattern = r"^(?:שלום|היי|הי|בוקר טוב|ערב טוב|אהלן)(?:\s+[א-ת]+)?(?:[\s,]+(?:מה\s+שלומך|מה\s+נשמע))?[\s!.,]*"
            if re.match(greeting_pattern, cleaned):
                cleaned = re.sub(greeting_pattern, f"{salutation} ", cleaned, count=1)
            else:
                cleaned = f"{salutation} {cleaned}"
        return cleaned.strip()

    # 3. Middle of conversation (אמצע, turns 4-5): Allow name once, but strip opening greetings
    if is_middle:
        pattern_with_name_simple = rf"^(?:שלום|היי|הי|אהלן|בוקר טוב|ערב טוב|צהריים טובים)[\s,]+(?:{re.escape(customer_name)})[\s?!.,-]*"
        cleaned = re.sub(pattern_with_name_simple, "", cleaned, flags=re.IGNORECASE).strip()
        return cleaned

    # 4. All other intermediate turns: Strictly strip customer name so the bot is not tiresome or repetitive!
    cleaned = strip_customer_name(cleaned, customer_name)
    return cleaned.strip()

